        "bj002",
        "bj003",
        "bj004",
        "bj005",
        "bj006"
      ],
      "poi_rationale": {
        "bj001": "故宫博物院：经典必访，室内/室外混合、推荐时长4小时，票价已知（60元），适合作为文化主景点。",
        "bj002": "天坛公园：以户外古建筑与公园为主，参观强度中等，适合早晨或休闲漫步。",
        "bj003": "颐和园：园林与湖景，游览时间较长（约4小时），景色优美，适合半日游。",
        "bj004": "中国国家博物馆：主要室内，适合雨天或高温日的替代方案，强度中等。",
        "bj005": "南锣鼓巷：胡同与小吃街，休闲放松、步行体验，时长短、强度低。",
        "bj006": "什刹海：湖景与夜游场景，安排傍晚或夜间轻松活动，强度低。"
      }
    },
    "weather_decisions": {
      "risk_days": [
        {
          "risk_type": "rain_or_high_temperature",
          "affected_poi_ids": [
            "bj002",
            "bj003",
            "bj005",
            "bj006"
